<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue'
import ArchivePageHeader from '../../../desktop/src/renderer/ui/ArchivePageHeader.vue'
import type { EventProjectionDto, ProjectedEventDto, EventOperationInput } from '../../../desktop/src/contracts/timeline/event-contracts'
import type { BookApi } from '../api/writing'
import { DraftStore } from './drafts'
import { messageOf } from '../api/http'
const props = defineProps<{ api: BookApi; owner: string }>()
const view = ref<EventProjectionDto | null>(null), error = ref(''), busy = ref(false), notice = ref(''), preview = ref<{ token: string; label: string } | null>(null)
const form = reactive({ time: '', characters: '', location: '', event: '', result: '' })
const store = new DraftStore(sessionStorage, props.owner, props.api.id)
const recovery = ref<typeof form | null>(null)
watch(form, value => { try { store.write('event:new', '', value) } catch { error.value = '恢复空间不足，请复制当前事件内容。' } }, { deep: true, flush: 'sync' })
async function read() { try { view.value = await props.api.events() } catch (e) { error.value = messageOf(e) } }
async function prepare(command: EventOperationInput, label: string) { busy.value = true; error.value = ''; try { const p = await props.api.previewEvent(command); preview.value = { token: p.token, label } } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
function create() { if (!view.value) return; return prepare({ kind: 'create', expectedOrderId: view.value.state.order.id, granularity: 'macro', content: { ...form, characters: form.characters.split(/[、,，\n]/).map(s => s.trim()).filter(Boolean), evidenceRefs: [], confidence: 1 } }, '确认并保存这条正式事件') }
function adopt(event: ProjectedEventDto) { if (!view.value) return; const lifecycle = view.value.state.lifecycles.find(x => x.eventId === event.eventId); if (!lifecycle) return; return prepare({ kind: 'adopt', eventId: event.eventId, expectedVersionId: event.versionId, expectedLifecycleId: lifecycle.id, expectedOrderId: view.value.state.order.id }, `将「${event.content.event}」采用为正式事件`) }
async function commit() { if (!preview.value) return; busy.value = true; try { view.value = await props.api.commitEvent(preview.value.token); preview.value = null; notice.value = '事件版本已保存。'; store.remove('event:new'); recovery.value = null } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
onMounted(async () => { await read(); const copy = store.read<typeof form>('event:new'); if (copy && Object.keys(form).every(k => typeof copy.data[k as keyof typeof form] === 'string')) recovery.value = copy.data })
</script>
<template><section class="form-page"><ArchivePageHeader eyebrow="03 / CHRONICLE" title="故事纪事" description="把时间、人物、地点与事件连成可追溯的故事线。" /><p v-if="error" class="error" role="alert">{{ error }} <button @click="read">重新读取</button></p><p v-if="notice" class="success" role="status">{{ notice }}</p><aside v-if="recovery" class="recovery-note">有未保存的事件表单。<button @click="Object.assign(form, recovery); recovery = null">恢复事件表单</button></aside><div class="events-layout"><form class="paper-card" @submit.prevent="create"><h3>新增事件</h3><label>时间<input v-model="form.time" required placeholder="第一日傍晚"></label><label>人物<input v-model="form.characters" required placeholder="林舟、叶青"></label><label>地点<input v-model="form.location" required placeholder="旧城"></label><label>发生了什么<textarea v-model="form.event" required rows="3"></textarea></label><label>结果与影响<textarea v-model="form.result" rows="2"></textarea></label><button class="primary" :disabled="busy || !view">预览并保存事件</button></form><div class="event-ledger"><p v-if="!view">正在读取纪事…</p><section v-else><h3>正式事件 <small>{{ view.approved.length }}</small></h3><article v-for="event in view.approved" :key="event.eventId" class="event-card"><span class="eyebrow">{{ event.content.time }}</span><h4>{{ event.content.event }}</h4><p>{{ event.content.characters.join('、') }} · {{ event.content.location }}</p><p>{{ event.content.result }}</p><span class="status-tag">{{ event.phase === 'planned' ? '计划发生' : event.phase === 'realized' ? '已发生' : '待核对' }}</span></article><p v-if="!view.approved.length" class="muted">新增事件并核对预览，确认后保存为正式事件。</p><h3>待采用候选 <small>{{ view.candidates.length }}</small></h3><article v-for="event in view.candidates" :key="event.eventId" class="event-card"><span class="eyebrow">{{ event.content.time }}</span><h4>{{ event.content.event }}</h4><p>{{ event.content.characters.join('、') }} · {{ event.content.location }}</p><p>{{ event.content.result }}</p><button :disabled="busy" @click="adopt(event)">核对并采用</button></article></section></div></div><div v-if="preview" class="modal-backdrop"><section v-dialog="() => { if (!busy) preview = null }" role="dialog" aria-modal="true" aria-labelledby="event-confirm" class="paper-card dialog-card"><h2 id="event-confirm">确认事件</h2><p>{{ preview.label }}</p><p class="muted">确认后的正式事件将成为后续规划与写作的事实依据。</p><div class="button-row"><button @click="preview = null">返回核对</button><button class="primary" :disabled="busy" @click="commit">确认</button></div></section></div></section></template>
